```c++
#include <iostream>
#include <restfulcxx/restfulcxx.hpp>

int main() {
    restfulcxx::Request request;
    restfulcxx::Response response;

    // Set up the API route
    restfulcxx::Route route = request.POST("/my_api");
    route << request.body() >> response.body();

    // Handle the request
    route << [](const std::string& body) {
        std::cout << "Request body: " << body << std::endl;
        response.set_status(200);
        response.set_body("Success!");
    };

    // Start the server
    restfulcxx::server::Server s(4000);
    s.add_route(route);
    s.run();

    return 0;
}
```

In this example, we define a route that handles POST requests to the "/my_api" path. The body of the request is extracted using the `request.body()` method, and the response is set to "Success!" with a status code of 200. The server is started on port 4000, and the `s.run()` method will keep the server running until the program is terminated.

